const body = $input.first().json.body || $input.first().json || {};
const customer = body.customer || {};
const property = body.property || {};

if (!customer.name || !customer.email || !customer.phone) {
  throw new Error('Customer name, email, and phone are required.');
}

if (!property.id || !property.title) {
  throw new Error('Selected plot ID and title are required.');
}

const plotId = property.plotNumber || property.id;
const plotLoc = property.locality || property.areaName || 'Chennai';
const mapsUrl = property.googleMapsUrl || `https://www.google.com/maps/dir/?api=1&destination=${property.latitude},${property.longitude}&travelmode=driving`;
const timeStr = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

const adminSubject = `New Plot Enquiry – [${plotId}] – [${plotLoc}]`;
const customerSubject = `[LLB Real Estate] Enquiry Confirmation: ${property.title} (${plotId})`;

const adminHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #f4f4f5; margin: 0; padding: 20px; color: #000; }
    .box { max-width: 600px; margin: 0 auto; background: #fff; border: 1.5px solid #000; border-radius: 8px; padding: 24px; }
    .title { font-size: 18px; font-weight: 900; letter-spacing: 1px; text-transform: uppercase; margin-bottom: 16px; }
    .row { padding: 8px 0; border-bottom: 1px solid #f0f0f0; font-size: 13px; }
    .lbl { color: #71717a; width: 35%; display: inline-block; font-weight: 500; }
    .val { color: #000; font-weight: 700; }
  </style>
</head>
<body>
  <div class="box">
    <div class="title">🚨 NEW PLOT ENQUIRY: ${plotId}</div>
    <div class="row"><span class="lbl">Customer Name:</span> <span class="val">${customer.name}</span></div>
    <div class="row"><span class="lbl">Customer Email:</span> <span class="val">${customer.email}</span></div>
    <div class="row"><span class="lbl">Customer Phone:</span> <span class="val">${customer.phone}</span></div>
    <div class="row"><span class="lbl">Plot ID & Title:</span> <span class="val">[${plotId}] ${property.title}</span></div>
    <div class="row"><span class="lbl">Plot Location:</span> <span class="val">${property.address || plotLoc}</span></div>
    <div class="row"><span class="lbl">Plot Price & Area:</span> <span class="val">${property.price} (${property.areaSqFt ? property.areaSqFt + ' Sq.Ft' : ''})</span></div>
    <div class="row"><span class="lbl">Google Maps Link:</span> <span class="val"><a href="${mapsUrl}">Open Google Maps Navigation</a></span></div>
    <div class="row"><span class="lbl">Enquiry Message:</span> <span class="val">${customer.message || 'Plot prospectus requested'}</span></div>
    <div class="row"><span class="lbl">Date & Time:</span> <span class="val">${timeStr} IST</span></div>
  </div>
</body>
</html>
`;

const customerHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #fff; margin: 0; padding: 24px; color: #000; }
    .box { max-width: 600px; margin: 0 auto; border: 1px solid #e4e4e7; border-radius: 8px; padding: 24px; }
    .hdr { font-size: 18px; font-weight: 900; margin-bottom: 12px; }
    .text { font-size: 13.5px; line-height: 1.6; color: #52525b; margin-bottom: 18px; }
  </style>
</head>
<body>
  <div class="box">
    <div class="hdr">LLB REAL ESTATE — ENQUIRY CONFIRMATION</div>
    <p class="text">Vanakkam ${customer.name},</p>
    <p class="text">Thank you for your enquiry regarding <strong>${property.title} (${plotId})</strong> in ${plotLoc}. We have received your submission and our assigned senior property advisor will reach out to you within 30 minutes.</p>
    <p class="text"><strong>Next Steps:</strong> Live site visits are scheduled with complimentary AC Cab pickup upon confirmation.</p>
  </div>
</body>
</html>
`;

return [{
  json: {
    adminEmail: 'prabakaransethu7@gmail.com',
    customerEmail: customer.email,
    adminSubject: adminSubject,
    adminHtml: adminHtml,
    customerSubject: customerSubject,
    customerHtml: customerHtml,
    plotId: plotId,
    customerName: customer.name
  }
}];

parameters.responseBody:
={
  "success": true,
  "message": "Enquiry successfully processed and notification delivered to prabakaransethu7@gmail.com",
  "plotId": "{{ $('Prepare Email Payloads').item.json.plotId }}",
  "customer": "{{ $('Prepare Email Payloads').item.json.customerName }}"
}
